import{_ as n,o as r,c as s,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const t="/bilder/berufskolleg/gruppenprozesse-bk-pruefungsnoten-eingeben.png",b=JSON.parse('{"title":"Schriftliche BK-Prüfungsnoten gruppenweise eingeben","description":"","frontmatter":{"title":"Schriftliche BK-Prüfungsnoten gruppenweise eingeben","source_pageid":1285,"source_revision":4701},"headers":[],"relativePath":"zeugnisse/berufskolleg/pruefungsergebnisse-eingeben-gruppenprozesse-bk-abschluss.md","filePath":"zeugnisse/berufskolleg/pruefungsergebnisse-eingeben-gruppenprozesse-bk-abschluss.md"}'),g={name:"zeugnisse/berufskolleg/pruefungsergebnisse-eingeben-gruppenprozesse-bk-abschluss.md"};function p(a,e,u,o,l,c){return r(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="schriftliche-bk-prufungsnoten-gruppenweise-eingeben" tabindex="-1">Schriftliche BK-Prüfungsnoten gruppenweise eingeben <a class="header-anchor" href="#schriftliche-bk-prufungsnoten-gruppenweise-eingeben" aria-label="Permalink to &quot;Schriftliche BK-Prüfungsnoten gruppenweise eingeben&quot;">​</a></h1><p>Tragen Sie schriftliche Prüfungsnoten für eine ausgewählte Schülergruppe ein und übernehmen Sie die fertige Tabelle in die Datenbank.</p><p><a href="/bilder/berufskolleg/gruppenprozesse-bk-pruefungsnoten-eingeben.png"><img src="'+t+'" alt="Geben Sie Prüfungsnoten gesammelt ein. Es lässt sich nach dem Fach filtern." loading="lazy"></a></p><p><em>Geben Sie Prüfungsnoten gesammelt ein. Es lässt sich nach dem Fach filtern.</em></p><p>Über den Gruppenprozess <strong>schriftliche Prüfungsnoten eingeben</strong> können Prüfungsnoten gesammelt bei einer Schülergruppe in den Reiter <em>Schüler ➜ BK-Abschluss</em> eingetragen werden.</p><p>Über die <strong>Sortierung</strong> lässt sich nach einem <em>Fach</em> filtern, die Sortierung ist dann alphabetisch nach <em>Name</em>.</p><p>Geben Sie die Noten je nach verwendetem Verfahren mit oder ohne Tendenzen ein, dann klicken Sie auf <code>In Datenbank übernehmen</code>. Die Noten werden nun bei den Schülern eingetragen. Ein Klick auf <em>Abbrechen</em> beendet den Prozess, ohne Änderungen an der Datenbank vorzunehmen.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Pr%C3%BCfungsergebnisse_eingeben_(Gruppenprozesse_BK-Abschluss)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4701.</p>',9)])])}const f=n(g,[["render",p]]);export{b as __pageData,f as default};
